                          <option value="21">Kepulauan Riau</option>

                          <option value="19">Kepulauan Bangka Belitung</option>

                          <option value="18">Lampung</option>

                          <option value="17">Bengkulu</option>

                          <option value="16">Sumatera Selatan</option>

                          <option value="15">Jambi</option>

                          <option value="14">Riau</option>

                          <option value="13">Sumatera Barat</option>

                          <option value="12">Sumatera Utara</option>

                          <option value="11">Aceh</option>
                        </select>
                      </label>
                    </div>
                    <div class="col-12 col-lg-6">
                      <label
                        class="col-form-label"
                        style="width: 100%"
                        id="registration-form-city-label"
                      >
                        Kota
                        <select
                          class="form-select form-select-lg"
                          style="
                            font-size: 12px;
                            border-color: var(--bs-gray-200);
                          "
                          name="city"
                        >
                          <option value="3175">Kota Adm. Jakarta Timur</option>

                          <option value="3174">
                            Kota Adm. Jakarta Selatan
                          </option>

                          <option value="3173">Kota Adm. Jakarta Barat</option>

                          <option value="3172">Kota Adm. Jakarta Utara</option>

                          <option value="3171">Kota Adm. Jakarta Pusat</option>

                          <option value="3101">Kab. Adm. Kep. Seribu</option>
                        </select>
                      </label>
                    </div>
                    <div class="col-12 col-lg-6">
                      <label class="col-form-label" style="width: 100%">
                        Kode Pos
                        <input
                          class="form-control form-control-lg"
                          type="text"
                          name="zip"
                          placeholder="Kode Pos"
                          style="
                            font-size: 12px;
                            border-color: var(--bs-gray-200);
                          "
                        />
                      </label>
                    </div>
                    <div class="col-12">
                      <div style="margin-bottom: 8px">
                        <label class="form-label" style="margin: 0px"
                          >Handphone</label
                        >
                        <div class="input-group">
                          <span
                            data-select="registration-dial-phone"
                            class="bg-light input-group-text"
                            style="
                              font-size: 12px;
                              border-color: var(--bs-gray-200);
                            "
                            >+62</span
                          >
                          <input
                            class="form-control form-control-lg"
                            type="text"
                            placeholder="Nomor Hanphone"
                            name="handphone"
                            style="
                              font-size: 12px;
                              border-color: var(--bs-gray-200);
                            "
                          />
                        </div>
                      </div>
                    </div>
                    <div class="col-12 col-md-6" data-container="password">
                      <label class="col-form-label" style="width: 100%">
                        Password
                        <input
                          class="form-control form-control-lg"
                          type="password"
                          name="password"
                          placeholder="Password"
                          style="
                            font-size: 12px;
                            border-color: var(--bs-gray-200);
                          "
                        />
                      </label>
                    </div>
                    <div class="col-12 col-md-6" data-container="password">
                      <label class="col-form-label" style="width: 100%">
                        Ulangi Password
                        <input
                          class="form-control form-control-lg"
                          type="password"
                          name="repeat-password"
                          placeholder="Ulangi Password"
                          style="
                            font-size: 12px;
                            border-color: var(--bs-gray-200);
                          "
                        />
                      </label>
                    </div>
                  </div>
                </form>
              </div>
            </div>
            <div class="modal-footer" style="border-top-style: dashed">
              <button
                class="btn btn-light btn-lg"
                type="button"
                data-bs-dismiss="modal"
                style="min-width: 100px; font-size: 12px"
              >
                Batal
              </button>
              <button
                class="btn btn-primary btn-lg"
                type="submit"
                form="registration-form"
                style="min-width: 100px; font-size: 12px"
              >
                Kirim
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>

