        border-radius: 25px;
        height: 85%;
        transition: all 0.4s;
        z-index: 10000;
      }

      iframe#rwlivechat-iframe {
        border-radius: 10px;
        border: none;
        height: 100%;
        width: 100%;
      }

      /*** for mobile view*/
      @media only screen and (max-width: 576px) {
        .rwlivechat-area {
          background-color: #46ccff;
          bottom: 0px;
          right: 0;
          height: 100%;
          width: 100%;
          border-radius: 0;
          position: fixed;
        }

        iframe#rwlivechat-iframe {
          border-radius: 0;
        }

        #rwlivechat-check:checked ~ .rwlivechat-area {
          height: 100%;
          bottom: 0;
        }
      }

      .rwlivechat-close {
        color: white;
        position: absolute;
        right: 15px;
        top: 15px;
        display: inline;
        cursor: pointer;
        width: 32px;
        height: 32px;
      }
